import React, { useRef } from "react";
import {
  useCurrentFrame,
  useVideoConfig,
  AbsoluteFill,
  interpolate,
  Easing,
  random,
} from '../remotionShim';
{/* Start Google Fonts Loader */ }
const useFontLoader = (fonts: string[]) => {
  const stableFonts = React.useMemo(() => {
    const unique = [...new Set(fonts.map(f => f.trim()))].sort();
    return unique;
  }, [fonts.join("|")]);

  React.useEffect(() => {
    const unloaded = stableFonts.filter(
      (font) =>
        !document.querySelector(
          `link[href*="${font.replace(/\s+/g, "+")}"]`
        )
    );

    if (unloaded.length === 0) return;

    const url = `https://fonts.googleapis.com/css2?${unloaded
      .map((font) => `family=${font.replace(/\s+/g, "+")}:wght@400;500;600;700`)
      .join("&")}&display=swap`;

    const link = document.createElement("link");
    link.rel = "stylesheet";
    link.href = url;

    document.head.appendChild(link);
  }, [stableFonts]);
};
{/* End Google Fonts Loader */ }



export type SaasTextRotatorProps = Record<string, any>;

const SaasTextRotator: React.FC<SaasTextRotatorProps> = ({
  backgroundColor = "#171717",
  cardBackgroundColor = "#1c1c1e",
  primaryTextColor = "#86868b",
  highlightTextColor = "#f5f5f7",
  transparentBackground = false,
  durationInSeconds = 15,
  headlineText = "Pro-level animation.",
  phrasesInput = "10× your views|Hook viewers instantly|Increase watch time|Stop the scroll", // Updated default for clarity
  cardBorderOpacity = 0.15,
  blurAmount = 40,
}) => {
  {/* Load Google Fonts */ }
  useFontLoader(["Inter"]);
  {/* End Load Google Fonts */ }

  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();

  const bgFinal = transparentBackground ? "transparent" : backgroundColor;

  // The 4 specific stages requested
  const stages = [
    { id: "count", text: "× your views" },
    { id: "eyes", text: "Hook viewers instantly" },
    { id: "timeline", text: "Increase watch time" },
    { id: "scroll", text: "Stop the scroll" },
  ];

  // Timing Logic
  const totalFrames = durationInSeconds * fps;
  const timePerPhrase = totalFrames / stages.length;
  const transitionDuration = fps * 0.8; 

  // Layout calculations
  const fontSize = width * 0.05; 
  const iconSize = fontSize * 1.2;

  // --- SUB-ANIMATION RENDERERS ---

  const renderCounter = (relFrame: number) => {
    // Count from 0 to 10
    const progress = interpolate(relFrame, [0, transitionDuration * 1.5], [0, 10], {
      easing: Easing.out(Easing.ease),
      extrapolateRight: "clamp",
    });
    const count = Math.round(progress);
    
    return (
      <span style={{ fontVariantNumeric: "tabular-nums" }}>
        {count}
      </span>
    );
  };

  const renderEyes = (relFrame: number) => {
    // Blink animation
    const blinkStart = transitionDuration;
    const eyeScaleY = interpolate(
      relFrame,
      [blinkStart, blinkStart + 5, blinkStart + 10],
      [1, 0.1, 1],
      { extrapolateLeft: "clamp", extrapolateRight: "clamp" }
    );

    return (
      <div style={{ display: "inline-flex", gap: fontSize * 0.2, margin: `0 ${fontSize * 0.2}px` }}>
        {[0, 1].map((i) => (
          <div
            key={i}
            style={{
              width: fontSize * 0.4,
              height: fontSize * 0.4,
              borderRadius: "50%",
              backgroundColor: highlightTextColor,
              transform: `scaleY(${eyeScaleY})`,
            }}
          />
        ))}
      </div>
    );
  };

  const renderTimeline = (relFrame: number) => {
    // Scrubbing animation
    const scrubProgress = interpolate(
      relFrame, 
      [transitionDuration * 0.5, timePerPhrase - transitionDuration], 
      [0, 100], 
      { extrapolateRight: "clamp", easing: Easing.linear }
    );

    return (
      <div
        style={{
          width: fontSize * 3,
          height: fontSize * 0.15,
          backgroundColor: "#333",
          borderRadius: fontSize * 0.1,
          marginTop: fontSize * 0.2,
          position: "relative",
          overflow: "hidden",
        }}
      >
        <div
          style={{
            position: "absolute",
            left: 0,
            top: 0,
            bottom: 0,
            width: `${scrubProgress}%`,
            backgroundColor: "#FF0000", // YouTube Red style
          }}
        />
        <div
            style={{
                position: "absolute",
                left: `${scrubProgress}%`,
                top: "50%",
                transform: "translate(-50%, -50%)",
                width: fontSize * 0.3,
                height: fontSize * 0.3,
                backgroundColor: "#FF0000",
                borderRadius: "50%",
            }}
        />
      </div>
    );
  };

  const renderScroll = (relFrame: number) => {
    // Slot machine jackpot style: Rapid scroll up, overshoot, slow settle
    const startOffset = transitionDuration * 0.3;
    const fastUpDuration = fps * 0.35; // Rapid ascent
    const settleDuration = fps * 0.8;  // Slow ease back

    const scrollY = interpolate(
        relFrame,
        [
            startOffset, 
            startOffset + fastUpDuration, 
            startOffset + fastUpDuration + settleDuration
        ],
        [
            fontSize * 12,   // Start deep below
            -fontSize * 0.5, // Overshoot upwards
            0                // Settle at center
        ],
        { 
            easing: Easing.bezier(0.2, 0.8, 0.2, 1), // Snappy start, smooth settle
            extrapolateLeft: "clamp",
            extrapolateRight: "clamp" 
        }
    );

    return (
        <div style={{
            display: "flex",
            gap: fontSize * 0.2,
            height: fontSize * 1.2,
            overflow: "hidden",
            alignItems: "center",
            marginTop: fontSize * 0.2
        }}>
           {[0, 1, 2].map(i => {
             const isCenter = i === 1;
             return (
                 <div 
                    key={i}
                    style={{
                        width: fontSize * 0.6,
                        height: fontSize * 1.06, // 9:16 approx
                        backgroundColor: isCenter ? highlightTextColor : "#333",
                        borderRadius: 4,
                        opacity: isCenter ? 1 : 0.5,
                        transform: `translateY(${scrollY}px)`,
                    }}
                 />
             )
           })}
        </div>
    );
  };

  return (
    <AbsoluteFill
      style={{
        backgroundColor: bgFinal,
        fontFamily: "Inter, -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, Helvetica, Arial, sans-serif",
        justifyContent: "center",
        alignItems: "center",
        transition: "none",
      }}
    >
      {/* Subtle Ambient Glow (Top Center) */}
      <div
        style={{
          position: "absolute",
          width: width * 1.2,
          height: height * 0.8,
          background: `radial-gradient(circle at 50% 0%, ${highlightTextColor}15 0%, transparent 60%)`,
          top: 0,
          left: "50%",
          transform: "translateX(-50%)",
          zIndex: 0,
        }}
      />

      {/* Main Content Container - Stacked Layout */}
      <div
        style={{
          position: "relative",
          zIndex: 1,
          width: "100%",
          display: "flex",
          flexDirection: "column",
          alignItems: "center",
          justifyContent: "center",
          gap: fontSize * 0.5,
        }}
      >
        {/* Static Headline */}
        <h2
          style={{
            width: "100%",
            textAlign: "center",
            color: primaryTextColor,
            fontSize: fontSize,
            fontWeight: 600,
            margin: 0,
            letterSpacing: "-0.02em",
            lineHeight: 1.1,
            whiteSpace: "nowrap",
          }}
        >
          {headlineText}
        </h2>

        {/* Rotating Content Container */}
        <div
          style={{
            width: "100%",
            height: fontSize * 2.5, // Increased height to accommodate graphics
            position: "relative",
            display: "flex",
            alignItems: "center",
            justifyContent: "center",
          }}
        >
          {stages.map((stage, index) => {
            const startFrame = index * timePerPhrase;
            const endFrame = startFrame + timePerPhrase;
            const relFrame = frame - startFrame; // Frame relative to start of this phrase

            // Entering
            const opacity = interpolate(
              frame,
              [startFrame, startFrame + transitionDuration, endFrame - transitionDuration, endFrame],
              [0, 1, 1, 0],
              { extrapolateRight: "clamp", extrapolateLeft: "clamp" }
            );

            // Vertical Slide
            const translateY = interpolate(
              frame,
              [startFrame, startFrame + transitionDuration, endFrame - transitionDuration, endFrame],
              [40, 0, 0, -40],
              {
                easing: Easing.bezier(0.2, 0.0, 0.2, 1),
                extrapolateRight: "clamp",
                extrapolateLeft: "clamp",
              }
            );

            // Blur Reveal Effect
            const blurVal = interpolate(
              frame,
              [startFrame, startFrame + transitionDuration, endFrame - transitionDuration, endFrame],
              [10, 0, 0, 10],
              { extrapolateRight: "clamp", extrapolateLeft: "clamp" }
            );

            const isVisible = frame >= startFrame - 15 && frame <= endFrame + 15;

            if (!isVisible) return null;

            return (
              <div
                key={index}
                style={{
                  position: "absolute",
                  top: 0,
                  left: 0,
                  width: "100%",
                  textAlign: "center",
                  opacity,
                  transform: `translateY(${translateY}px)`,
                  filter: `blur(${blurVal}px)`,
                  willChange: "transform, opacity, filter",
                  display: "flex",
                  flexDirection: "column",
                  justifyContent: "center",
                  alignItems: "center",
                  height: "100%",
                }}
              >
                {/* Content Wrapper */}
                <div style={{
                    display: "flex",
                    flexDirection: "column",
                    alignItems: "center",
                    justifyContent: "center",
                }}>
                    
                    {/* Main Text Line */}
                    <span
                    style={{
                        fontSize: fontSize,
                        fontWeight: 600,
                        background: `linear-gradient(135deg, ${highlightTextColor} 0%, ${highlightTextColor}aa 100%)`,
                        WebkitBackgroundClip: "text",
                        WebkitTextFillColor: "transparent",
                        backgroundClip: "text",
                        color: "transparent",
                        letterSpacing: "-0.035em",
                        lineHeight: 1.1,
                        whiteSpace: "nowrap",
                        display: "flex",
                        alignItems: "center",
                    }}
                    >
                        {/* Custom Text/Graphic Mix based on Stage */}
                        {stage.id === "count" && (
                            <>
                                {renderCounter(relFrame)}
                                {stage.text}
                            </>
                        )}
                        
                        {stage.id === "eyes" && (
                            <>
                                Hook {renderEyes(relFrame)} viewers
                            </>
                        )}
                         {stage.id === "eyes" && (
                             <span style={{ marginLeft: fontSize * 0.2 }}>instantly</span>
                         )}

                        {(stage.id === "timeline" || stage.id === "scroll") && stage.text}

                    </span>

                    {/* Secondary Graphics (Below Text) */}
                    {stage.id === "timeline" && renderTimeline(relFrame)}
                    {stage.id === "scroll" && renderScroll(relFrame)}
                    
                </div>
              </div>
            );
          })}
        </div>
      </div>
    </AbsoluteFill>
  );
};

export default SaasTextRotator;